/// Builds every tenancy service from `db` (each wired to its own Postgres repository —
/// a cheap clone of the same connection pool handle — `KernelIdGenerator`, and
/// `SystemClock`) plus the wired `AuthnSvc` from `cfg.authn`: the OIDC authenticator
/// over the configured JWKS cache backend, the Pg authn repositories, and the
/// per-issuer `JitPolicy`. Fails when the Redis JWKS cache is configured but
/// unreachable (`RedisJwksCache::connect` is the async part) — `IamConfig::validate`
/// has already guaranteed `redis_url` is present and every issuer parses.
///
/// **Authorizer wiring (SMA-444 Task 15/21):** ONE shared [`Generations`] handle — the
/// `memory` backend, or a `redis` `RedisHandle` selected by `authz.cache.backend`
/// (Task 21) — feeds the authz Postgres stores (`PgPolicyStore`, `PgRoleGrantStore`,
/// `PgEntitySliceLoader`) AND the three tenancy repositories below, so a policy/grant
/// change bumps `policy_gen` and a tenancy structure/status change bumps `entity_gen` —
/// both observed by the SAME counters `CedarAuthorizer`'s decision cache keys off. When
/// `redis` is configured, the SAME `RedisHandle` (`redis_conn` below) also backs
/// the decision cache (`RedisDecisionCache`) and the entity-slice cache (`SliceCache`) —
/// one shared connection, not three independent ones. Fails fast (mirroring the JWKS
/// redis cache below) when redis is configured but unreachable — `IamConfig::validate`
/// has already guaranteed `redis_url` is present. The initial [`PolicySnapshot`] build
/// reads whatever the policy store currently holds — [`bootstrap::reconcile_starter`]
/// (SMA-444 Task 17; converge-to-code since SMA-477) runs first and CONVERGES the starter
/// Cedar policy set + the system role catalog to the code-defined content on every boot
/// (seeding it on a fresh/unseeded database), so the initial snapshot always compiles at
/// least that starter set, never an empty or drifted one.
pub async fn new(db: DatabaseConnection, cfg: &IamConfig) -> Result<AppState, AuthnError> {
    let authz_cfg = &cfg.authz;
    // SMA-485 D5: the handle is paired with the URL it was OPENED with, not left for a
    // later, independent re-read of `authz_cfg.cache.redis_url` to guess at. The API-key
    // cache below decides whether to reuse this connection by comparing against that URL, so
    // pairing them makes the comparison structurally be against this handle's own origin —
    // and deletes the `(Some(handle), None)` state that a second read would have to handle.
    let (gens, redis_conn): (Generations, Option<(RedisHandle, &str)>) = match authz_cfg.cache.backend {
        AuthzCacheBackend::Memory => (Generations::memory(), None),
        AuthzCacheBackend::Redis => {
            // `IamConfig::validate` rejects a redis backend without a URL at boot; a
            // `None` here is a wiring defect, not an operator error.
            let redis_url = authz_cfg
                .cache
                .redis_url
                .as_deref()
                .ok_or_else(|| AuthnError::Backend("authz.cache.backend = \"redis\" without redis_url (IamConfig::validate must run first)".into()))?;
            let conn = connect_redis(redis_url, RedisRole::Authz).await?;
            (Generations::from_connection(conn.clone()), Some((conn, redis_url)))
        }
    };

    let orgs = OrganizationService::new(PgOrganizationRepository::new(db.clone(), gens.clone()), KernelIdGenerator, SystemClock);
    let teams = TeamService::new(PgTeamRepository::new(db.clone(), gens.clone()), KernelIdGenerator, SystemClock);
    let projects = ProjectService::new(
        PgProjectRepository::new(db.clone(), gens.clone()),
        PgTeamRepository::new(db.clone(), gens.clone()),
        KernelIdGenerator,
        SystemClock,
    );
    let memberships = MembershipService::new(PgMembershipRepository::new(db.clone()), KernelIdGenerator, SystemClock);
    // SMA-446 Task B7 (copies Task B4-B6's `roles`/`policies`/`api_keys` wiring below):
    // `users` drives its principal+user insert + outbox event through its OWN
    // `SeaOrmUnitOfWork` transaction (`user_uow` — a fresh instance is fine, `db.clone()` is
    // a cheap `Arc`-backed pool handle). OUTBOX-ONLY: no audit entry, no generation bump —
    // principal creation is not in the AC audit set.
    let user_uow: Arc<dyn UnitOfWork> = Arc::new(SeaOrmUnitOfWork::new(db.clone()));
    let user_outbox: Arc<dyn Outbox> = Arc::new(PgOutbox::new(cfg.outbox.wake_on_commit));
    let users = CreateUser::new(CreateUserDeps {
        repo: PgPrincipalRepository::new(db.clone()),
        uow: user_uow,
        outbox: user_outbox,
        id_gen: KernelIdGenerator,
        clock: SystemClock,
    });

    let policy_store: Arc<dyn PolicyStore> = Arc::new(PgPolicyStore::new(db.clone(), gens.clone()));
    let role_grant_store: Arc<dyn RoleGrantStore> = Arc::new(PgRoleGrantStore::new(db.clone(), gens.clone()));

    // SMA-446 Task A10/A12 (built here, ahead of `reconcile_starter` just below and
    // `roles` further down, since both need it too): the audit-log read+write handle.
    // `audit_log` is a single shared `Arc<dyn AuditLog>` (`PgAuditLog` over `db`) that the
    // read-side `audit_query` (A10) reads through, the denial-audit drain (A12, spawned by
    // `main.rs`) writes buffered denials into, `RoleService`'s in-txn `AuditLog::record`
    // writes through (B4), AND boot reconciliation's out-of-band audit entries write
    // through (SMA-477) — one store instance, not several (mirrors `role_grant_store`'s
    // single-shared-`Arc` posture). It is stashed on the returned state (`audit_log`
    // field, reachable via `audit_sink()`) so `main.rs` can hand it to `drain.run(sink,
    // shutdown)`. Built ABOVE the reconcile call so reconcile shares this SAME instance
    // rather than a second, windowless one — `with_query_window` takes `mut self` and
    // returns `Self`, so there is no way to build it twice and still share one `Arc`.
    let audit_log: Arc<dyn AuditLog> = Arc::new(PgAuditLog::new(db.clone()).with_query_window(cfg.audit.query_default_window_days, cfg.audit.query_max_window_days));

    // SMA-477: a SECOND `PgPolicyStore` value, deliberately — the reconciler needs
    // `SystemPolicyReconciler` and `policy_store` above is typed as `Arc<dyn PolicyStore>`,
    // which cannot be downcast to it. That costs nothing and changes nothing, because what
    // has to be shared is not the struct: it is the `db` pool handle and the `Generations`
    // handle, both cloned from the same values `policy_store` holds (each an `Arc` inside).
    // So a converged policy's `policy_gen` bump lands on the very counter this replica's own
    // snapshot reads, and on the shared redis counter every other replica polls.
    let policy_reconciler: Arc<dyn SystemPolicyReconciler> = Arc::new(PgPolicyStore::new(db.clone(), gens.clone()));
    let role_reconciler: Arc<dyn SystemRoleReconciler> = Arc::new(PgSystemRoleReconciler::new(db.clone()));
    let reconcile_deps = bootstrap::ReconcileStarterDeps {
        policies: policy_reconciler,
        roles: role_reconciler,
        audit: audit_log.clone(),
        ids: KernelIdGenerator,
        clock: SystemClock,
    };
    bootstrap::reconcile_starter(&reconcile_deps).await.map_err(|e| AuthnError::Backend(Box::new(e)))?;

    let snapshot = Arc::new(
        PolicySnapshot::new(policy_store.clone(), role_grant_store.clone())
            .await
            .map_err(|e| AuthnError::Backend(Box::new(e)))?,
    );
    // `slices`/`decisions` backend selection mirrors `gens` above: `memory` when no redis
    // connection was opened, `redis` sharing `redis_conn` when one was (never a second,
    // independent connection).
    let slices: Arc<dyn EntitySliceLoader> = {
        let pg_loader: Arc<dyn EntitySliceLoader> = Arc::new(PgEntitySliceLoader::new(db.clone(), gens.clone()));
        match &redis_conn {
            Some((conn, _)) => Arc::new(SliceCache::from_connection(pg_loader, conn.clone(), authz_cfg.slice_cache_ttl_secs)) as Arc<dyn EntitySliceLoader>,
            None => pg_loader,
        }

        let api_key_hasher = HmacSecretHasher::new(api_key_pepper);
        let api_key_cache: Arc<dyn ApiKeyValidationCache> = match cfg.api_keys.introspect_cache.backend {
            ApiKeyCacheBackend::Memory => Arc::new(MemoryApiKeyCache::new(cfg.api_keys.introspect_cache.ttl_secs)),
            ApiKeyCacheBackend::Redis => {
                // SMA-485: reuse the SHARED `redis_conn` opened above ONLY when the two
                // configured URLs match textually after trimming (`shares_one_connection`, D1) —
                // that is SMA-444 Task 21's one-connection-per-deployment optimisation, and it is
                // sound precisely when both URLs name the same endpoint. Before SMA-485 the reuse
                // was unconditional, so an operator who pointed `api_keys.introspect_cache` at a
                // second Redis got the authz one anyway: the URL `IamConfig::validate` REQUIRES
                // was then discarded, and SMA-476 D1's per-connection breaker isolation silently
                // did not hold (one connection, one breaker, so an authz outage short-circuited
                // API-key introspection against a healthy backend).
                //
                // The URL is read BEFORE the match, so a missing one is a loud wiring defect
                // rather than a silent fallback to the authz connection (D2) — matching the
                // authz arm above and the JWKS arm below. `IamConfig::validate` rejects that
                // config at boot; `AppState::new` takes a bare `&IamConfig`, so this stays a
                // real fallible step here.
                let api_key_url = cfg
                    .api_keys
                    .introspect_cache
                    .redis_url
                    .as_deref()
                    .ok_or_else(|| AuthnError::Backend("api_keys.introspect_cache.backend = \"redis\" without redis_url (IamConfig::validate must run first)".into()))?;
                //
                // The dial failure is re-wrapped with the config key that caused it. Before
                // SMA-485 there was at most ONE Redis dial in this function, so a bare
                // "Connection refused" was unambiguous; now there can be two, and this is the one
                // whose URL was previously ignored — i.e. the one most likely to hold a stale or
                // placeholder value that has never been dialled before. The message names the KEY,
                // never the URL: a `redis::RedisError` does not echo the URL it failed on, and
                // that posture (SMA-476 D4) is deliberate, since this string reaches the logs.
                let conn = match &redis_conn {
                    Some((conn, authz_url)) if shares_one_connection(authz_url, api_key_url) => conn.clone(),
                    _ => connect_redis(api_key_url, RedisRole::ApiKeys)
                        .await
                        .map_err(|e| AuthnError::Backend(format!("api_keys.introspect_cache.redis_url is unreachable ({e}) — since SMA-485 it is dialled rather than ignored").into()))?,
                };
                Arc::new(RedisApiKeyCache::from_connection(conn, cfg.api_keys.introspect_cache.ttl_secs))
            }
        };

        let api_key_auth = AuthenticateApiKey::new(
            PgApiKeyRepository::new(db.clone()),
            PgPrincipalRepository::new(db.clone()),
            api_key_hasher.clone(),
            SystemClock,
            api_key_cache.clone(),
            PgMembershipRepository::new(db.clone()),
            cfg.api_keys.clone(),
        );
        // SMA-446 Task B7 (copies Task B4-B6's UoW-wiring pattern above): `service_accounts`
        // drives its create/archive mutation + outbox event through its OWN `SeaOrmUnitOfWork`
        // transaction (`service_account_uow` — a fresh instance is fine, `db.clone()` is a
        // cheap `Arc`-backed pool handle). OUTBOX-ONLY, like `users` above: no audit entry, no
        // generation bump. `archive`'s post-commit cache-evict runs over the SAME
        // `api_key_cache` handle `api_key_auth`/`api_keys` read/evict through.
        let service_account_uow: Arc<dyn UnitOfWork> = Arc::new(SeaOrmUnitOfWork::new(db.clone()));
        let service_account_outbox: Arc<dyn Outbox> = Arc::new(PgOutbox::new(cfg.outbox.wake_on_commit));
        let service_accounts = ServiceAccountService::new(ServiceAccountServiceDeps {
            repo: PgServiceAccountRepository::new(db.clone()),
            keys: Arc::new(PgApiKeyRepository::new(db.clone())) as Arc<dyn ApiKeyRepository>,
            cache: api_key_cache.clone(),
            authorize: authorize.clone(),
            uow: service_account_uow,
            outbox: service_account_outbox,
            ids: KernelIdGenerator,
            clock: SystemClock,
        });
        // SMA-446 Task B6 (copies Task B4/B5's `roles`/`policies` wiring above): `api_keys`
        // drives its issue/revoke mutation + outbox event + audit entry through its OWN
        // `SeaOrmUnitOfWork` transaction (`api_key_uow` — a fresh instance is fine, `db.clone()`
        // is a cheap `Arc`-backed pool handle, mirrors `role_uow`/`policy_uow`). Unlike
        // `roles`/`policies`, there is NO post-commit generation bump here — API-key
        // issue/revoke never touch `policy_gen`/`entity_gen` (`ApiKeyServiceDeps`'s own doc);
        // the post-commit step this service DOES run (`revoke`'s cache-evict) is over the SAME
        // `api_key_cache` handle `api_key_auth` reads through, already threaded below.
        let api_key_uow: Arc<dyn UnitOfWork> = Arc::new(SeaOrmUnitOfWork::new(db.clone()));
        let api_key_outbox: Arc<dyn Outbox> = Arc::new(PgOutbox::new(cfg.outbox.wake_on_commit));
        let api_keys = ApiKeyService::new(ApiKeyServiceDeps {
            keys: PgApiKeyRepository::new(db.clone()),
            service_accounts: PgServiceAccountRepository::new(db.clone()),
            grants: role_grant_store.clone(),
            authorize: authorize.clone(),
            hasher: api_key_hasher,
            entropy: OsRngKeyEntropy,
            cache: api_key_cache,
            uow: api_key_uow,
            outbox: api_key_outbox,
            audit: audit_log.clone(),
            ids: KernelIdGenerator,
            clock: SystemClock,
            config: cfg.api_keys.clone(),
        });

        let authn_cfg = &cfg.authn;
        if authn_cfg.accept_invalid_tls {
            tracing::warn!("accept_invalid_tls is enabled: TLS certificate verification for IdP discovery/JWKS fetches is DISABLED — test-only configuration, never use in production");
        }
        let fetcher = HttpJwksFetcher::new(Duration::from_secs(authn_cfg.http_timeout_secs), authn_cfg.accept_invalid_tls)?;
        let ttl = Duration::from_secs(authn_cfg.jwks_ttl_secs);
        let cooldown = Duration::from_secs(authn_cfg.jwks_refresh_cooldown_secs);
        let authenticator = match authn_cfg.jwks_cache.backend {
            JwksCacheBackend::Memory => WiredAuthenticator::Memory(Arc::new(OidcAuthenticator::new(
                authn_cfg.issuers.clone(),
                JwksProvider::new(fetcher, InMemoryJwksCache::new(), SystemClock, ttl, cooldown),
                authn_cfg.leeway_secs,
                authn_cfg.max_token_bytes,
            )?)),
            JwksCacheBackend::Redis => {
                // `IamConfig::validate` rejects a redis backend without a URL at boot; a
                // `None` here is a wiring defect, not an operator error.
                let redis_url = authn_cfg
                    .jwks_cache
                    .redis_url
                    .as_deref()
                    .ok_or_else(|| AuthnError::Backend("jwks_cache.backend = \"redis\" without redis_url (IamConfig::validate must run first)".into()))?;
                let cache = RedisJwksCache::connect(redis_url, authn_cfg.jwks_ttl_secs).await?;
                WiredAuthenticator::Redis(Arc::new(OidcAuthenticator::new(
                    authn_cfg.issuers.clone(),
                    JwksProvider::new(fetcher, cache, SystemClock, ttl, cooldown),
                    authn_cfg.leeway_secs,
                    authn_cfg.max_token_bytes,
                )?))
            }
        };

        let jit_flags = authn_cfg
            .issuers
            .iter()
            .map(|issuer_cfg| Issuer::parse(&issuer_cfg.issuer).map(|issuer| (issuer, issuer_cfg.jit_provisioning)))
            .collect::<Result<Vec<_>, _>>()
            .map_err(|e| AuthnError::Backend(e.to_string().into()))?;
        let authn = AuthenticateToken::new(
            authenticator,
            PgExternalIdentityRepository::new(db.clone()),
            PgPrincipalRepository::new(db.clone()),
            PgMembershipRepository::new(db.clone()),
            KernelIdGenerator,
            SystemClock,
            JitPolicy::from_issuers(&jit_flags),
        );

        Ok(AppState {
            db,
            orgs,
            teams,
            projects,
            memberships,
            users,
            authn,
            authz,
            snapshot,
            introspect_body_limit: cfg.authn.max_token_bytes + INTROSPECT_BODY_OVERHEAD_BYTES,
            roles,
            policies,
            authorize,
            role_grant_store,
            enforce_tenancy: authz_cfg.enforce_tenancy,
            bootstrap_seeder,
            api_key_auth,
            service_accounts,
            api_keys,
            api_key_prefix: cfg.api_keys.key_prefix.clone(),
            api_key_introspect_body_limit: cfg.api_keys.max_token_bytes + INTROSPECT_BODY_OVERHEAD_BYTES,
            audit_query,
            dead_letters,
            retirement,
            audit_log,
            denial_drain: Arc::new(Mutex::new(Some(denial_drain))),
        })
    }
}

/// Opens `redis_url` and wraps it in a breaker-guarded [`RedisHandle`] — shared by every
/// redis-backed cache `AppState::new` wires (the authz `Generations`/`RedisDecisionCache`/
/// `SliceCache` trio, SMA-444 Task 21; the API-key `RedisApiKeyCache`, SMA-445 Task 19, when
/// [`shares_one_connection`] says its configured URL matches the authz one — otherwise that cache
/// gets its OWN handle from this same function, SMA-485). The `redis_conn` LOCAL BINDING in
/// `AppState::new` is not to be confused with the [`crate::adapters::redis_conn`] MODULE this
/// delegates to. Mirrors `RedisJwksCache::connect`'s connect pattern.
///
/// Delegates to [`crate::adapters::redis_conn::connect`] for the tuned reconnect retry budget
/// (SMA-473) and the per-connection circuit breaker (SMA-476) — this function owns only the
/// `AuthnError` mapping. `role` labels this connection's breaker metrics; a SHARED connection
/// reports every command as `authz`, including the API-key cache's (SMA-476 D10, as amended by
/// SMA-485 D1: sharing now requires the two URLs to match).
async fn connect_redis(redis_url: &str, role: RedisRole) -> Result<RedisHandle, AuthnError> {
    crate::adapters::redis_conn::connect(redis_url, role).await.map_err(|e| AuthnError::Backend(Box::new(e)))
}

/// Whether the API-key introspect cache may reuse the authz connection: textual equality of the
/// two configured URLs after trimming, **not** endpoint identity (SMA-485 D1).
///
/// `redis://cache:6379` and `redis://cache:6379/0` name one backend spelled two ways and
/// deliberately get two connections — erring toward a second connection is wasteful, never wrong
/// (the key namespaces are disjoint: `iam:apikey:` vs `iam:authz:*` vs `iam:jwks:`), whereas
/// erring the other way is what SMA-485 exists to fix. Normalising through redis-rs was declined
/// because it would not resolve the motivating case either — `redis://localhost:6379` vs
/// `redis://127.0.0.1:6379` differs by HOST, which no parser resolves at config-read time — while
/// putting credential comparison (`ConnectionInfo` carries `password`) into the composition root.
///
/// The trim is load-bearing, not cosmetic. `IamConfig::validate` trims `authn.issuers` but no
/// `redis_url`, and URL parsing strips surrounding C0 controls and spaces — so a trailing newline
/// from an env-var override dials perfectly well and would differ only textually, silently
/// splitting a deployment the operator believes is unified.
pub(crate) fn shares_one_connection(authz_url: &str, api_key_url: &str) -> bool {
    authz_url.trim() == api_key_url.trim()
}

/// Liveness only — stateless, so it is testable without a database.
pub fn health_router() -> Router {
    Router::new().route("/healthz", get(healthz))
}

/// DB-backed readiness alone, on its own `Router<AppState>`-turned-`Router` (mirrors
/// [`health_router`]'s standalone posture) — split out of the old inline `router()` body so
/// [`router`] and [`serve_http`] can each merge it in at the top level, OUTSIDE both
/// [`app_routes`]'s `http_metrics_layer` and (in `serve_http`) `TraceLayer`/`TimeoutLayer`
/// (SMA-446 Unit 3): a 15s Prometheus scrape hitting `/metrics`, or a liveness/readiness
/// poller hitting `/healthz`/`/readyz`, must not spam a request-span trace log every tick nor
/// inflate the RED (rate/errors/duration) metrics with health-check traffic.
fn readyz_router(state: AppState) -> Router {
    Router::new().route("/readyz", get(readyz)).with_state(state)
}

/// The `/v1` tenancy API + authn/api-key introspection — every route EXCEPT `/healthz`/
/// `/readyz` (see [`readyz_router`]/[`health_router`], deliberately excluded). The tenancy
/// routes (organizations/teams/projects/memberships/users) sit on their own sub-router
/// carrying the bearer-enforcement `route_layer` (D14 — attached HERE, inside `app_routes`,
/// not in `serve_http`, so the `oneshot` test harness exercises it); `POST
/// /v1/authn/introspect` and `POST /v1/authn/api-keys/introspect` are merged OUTSIDE that
/// layer and stay unauthenticated (spec §7.4). [`paigasus_observability::http_metrics_layer`]
/// is applied LAST, over this entire (merged) subtree — so every app route, matched or not,
/// including a 401 from the bearer-enforcement middleware, is recorded — but NEITHER
/// `/healthz` NOR `/readyz` NOR `/metrics` is, since none of them are part of this `Router`
/// instance (SMA-446 Unit 3, mirrors the gateway's identical `http_metrics_layer` placement,
/// `paigasus-gateway::adapters::http::router`, minus the health-route inclusion that router
/// deliberately keeps and this one deliberately excludes).

// `AuthzConfig` field has a sensible default (see `AuthzConfig`'s doc).
#[derive(Serialize)]
struct AuthzDefaults {
    enforce_tenancy: bool,
    policy_cache_ttl_secs: u64,
    slice_cache_ttl_secs: u64,
    decision_cache_ttl_secs: u64,
    refresh_interval_secs: u64,
    cache: AuthzCacheConfig,
    bootstrap_admins: Vec<BootstrapAdmin>,
}

// Mirrors `ApiKeyConfig` field-for-field, EXCEPT `pepper`'s TYPE: this struct only ever feeds
// figment's default LAYER (`Serialized::defaults`), never gets logged/dumped itself, so a
// plain (unredacted) `String` is fine here — figment still deserializes the eventual merged
// value into `ApiKeyConfig.pepper: RawPepper` regardless of which layer (default/toml/env)
// supplied it. The default is the empty string, which is deliberately INVALID
// (`Pepper::from_config("")` fails with `TooShort`) — see `ApiKeyConfig`'s doc for why that's
// caught at `validate()` rather than at figment extraction.
#[derive(Serialize)]
struct ApiKeyDefaults {
    pepper: String,
    key_prefix: String,
    max_token_bytes: usize,
    default_expiry_days: Option<u32>,
    last_used_throttle_secs: u64,
    introspect_cache: ApiKeyCacheConfig,
}

// Mirrors `AuditConfig` field-for-field. A 4096-entry denial buffer comfortably absorbs a
// denial burst between drain wakes without back-pressure while staying a modest bounded
// footprint (each queued entry is a handful of small strings). The SMA-467 `retention`/
// query-window defaults mirror the spec's steady-state values (see `RetentionConfig::default`
// and this struct's own `Default` below for the rationale of each).
#[derive(Serialize)]
struct AuditDefaults {
    denial_buffer_capacity: usize,
    retention: RetentionConfig,
    query_default_window_days: u32,
    query_max_window_days: u32,
}

// Mirrors `OutboxConfig` field-for-field. `poll_interval_secs = 5` / `batch_size = 100` are the
// spec-example steady-state values (frequent enough to keep `event_outbox` drained close to real
// time, generous enough to absorb a burst without an oversized single transaction);
// `relay_enabled = true` because the relay is the intended steady-state behavior (see
// `OutboxConfig`'s doc for the disabled path). `max_attempts = 60` (SMA-471 D9, raised from 5) so
// a routine broker restart does not dead-letter the in-flight backlog before it recovers.
// `publisher` defaults to the `tracing` backend (see `PublisherConfig`'s doc) so an absent
// `[outbox.publisher]` block — and every pre-SMA-471 config file — keeps working with no broker
// available.
#[derive(Serialize)]
struct OutboxDefaults {
    relay_enabled: bool,
    poll_interval_secs: u64,
    batch_size: u64,
    max_attempts: u32,
    wake_on_commit: bool,
    wake_debounce_ms: u64,
    // Plain `String`, not `RedactedUrl` — same exception `ApiKeyDefaults::pepper` takes: this
    // struct only ever feeds figment's default LAYER and is never itself logged or dumped, and a
    // `RedactedUrl` here would serialize the literal `"<redacted>"` INTO that layer. The default
    // is `None` either way; figment still deserializes the merged value into
    // `OutboxConfig::listen_database_url: Option<RedactedUrl>` whichever layer supplied it.
    listen_database_url: Option<String>,
    retention: OutboxRetentionConfig,
    publisher: PublisherConfig,
}

impl Default for Defaults {
